// Edit these to control the generated descriptions.
// min_words / max_words are word counts.
const settings = {
  min_words: 100,
  max_words: 250,
  max_attempts: 3,
  rules: [
    "Open with one sentence that names the product, including the brand, and says what it does for the customer",
    "Follow with the key benefits, then how and when to use it, using only information from the source data",
    "Write two or three short plain-text paragraphs. Do not use headings, bullet points, or HTML",
    "Write to the customer using you and your",
    "Use the product type and the words shoppers search for naturally. Do not stuff keywords or list them at the end",
    "Include size, coverage, and other specifications when they appear in the source data",
    "Do not include the MPN or SKU",
    "Do not use promotional words such as best, sale, new, free shipping, or guaranteed",
    "Do not use all caps, emojis, or symbols such as ! * $ ® ™",
    "Only include attributes and claims that appear in the source data. Do not invent specifications or results"
  ],
  // Example descriptions that show the style you want. Each is a plain string.
  examples: [
    "{brand} Tall Fescue Grass Sun or Shade Fertilizer/Seed/Soil Improver gives you a thicker, greener lawn in full sun or partial shade. Each bag combines tall fescue grass seed with a starter fertilizer and a soil improver, so you can seed, feed, and condition your soil in one application.\n\nTall fescue grows deep roots that help it handle heat, dry spells, and heavy foot traffic, which makes it a good fit for busy family lawns. The soil improver helps the seed hold moisture while it germinates, and the fertilizer supports quick, even growth. Each {size} bag covers up to {coverage} sq. ft.\n\nUse it to start a new lawn, overseed thin areas, or repair bare patches. Spread it evenly with a broadcast or drop spreader, rake it lightly into the soil, and keep the area moist until the new grass is established."
  ]
};

return [{ json: { ...$input.first().json, ...settings } }];

// Universal Search response shape can vary, so probe common containers.
// Emit one item per candidate URL (top 3) so each can be scraped and checked
// with product matching in turn.
const product = $('Sample Product').first().json;
const res = $input.first().json;

let list = res.results || res.data || res.items || res.pages || res.urls || [];
if (!Array.isArray(list) && Array.isArray(res)) list = res;
if (!Array.isArray(list)) list = [];

const urls = list
  .map(r => (typeof r === 'string') ? r : (r.url || r.link || r.source_url || r.page_url || ''))
  .filter(Boolean)
  .slice(0, 3);

return urls.map((source_url, i) => ({
  json: {
    ...product,
    source_url,
    candidate_rank: i + 1
  }
}));

