// Build the description request from the matched page's scrape, the rules,
// and the examples in Description Settings.
const settings = $('Description Settings').first().json;
const candidate = $('Loop Over Candidates').item.json;
const scraped = $('Smart Scrape').item.json || {};
const s = scraped.data || scraped.result || scraped;

// Scraped title goes in `title`. Everything else scraped from the page
// (description, specs, brand, MPN, etc.) goes in `description`.
const toText = v => (v == null || v === '') ? '' : (typeof v === 'string' ? v : JSON.stringify(v));
const imageKeys = ['image_urls', 'image_url', 'images'];
const details = Object.entries(s)
  .filter(([k, v]) => k !== 'title' && k !== 'description' && !imageKeys.includes(k) && toText(v))
  .map(([k, v]) => `${k}: ${toText(v)}`);
const description = [toText(s.description), ...details].filter(Boolean).join('\n');

let image_url = '';
if (Array.isArray(s.image_urls)) image_url = s.image_urls[0] || '';
else if (s.image_url) image_url = s.image_url;
else if (Array.isArray(s.images)) image_url = s.images[0] || '';

return [{
  json: {
    product: {
      title: s.title || candidate.title || '',
      description,
      image_url
    },
    customer_rules: [
      ...settings.rules,
      `Keep the description between ${settings.min_words} and ${settings.max_words} words`,
      `The brand is "${candidate.brand}"`
    ],
    examples: settings.examples,
    candidate: {
      title: candidate.title,
      brand: candidate.brand,
      mpn: candidate.mpn,
      source_url: candidate.source_url
    }
  }
}];

// Check the generated description against the word limits.
// Each run of this node is one attempt.
const settings = $('Description Settings').first().json;
const res = $input.first().json;
const raw = res.product_description ?? res.description ?? res;
const description = (typeof raw === 'string' ? raw : '').trim();
const words = description.replace(/<[^>]*>/g, ' ').split(/\s+/).filter(Boolean).length;
const attempt = $runIndex + 1;

let issue = '';
if (!description) issue = 'empty';
else if (words < settings.min_words) issue = 'too_short';
else if (words > settings.max_words) issue = 'too_long';

return [{
  json: {
    description,
    words,
    min_words: settings.min_words,
    max_words: settings.max_words,
    attempt,
    valid: issue === '',
    issue,
    can_retry: attempt < settings.max_attempts
  }
}];

// Resend the original request with an extra rule telling the model
// how far off the last description was.
const base = $('Build Description Request').first().json;
const v = $input.first().json;

const feedback = v.issue === 'empty'
  ? `The previous attempt returned no description. Write a description between ${v.min_words} and ${v.max_words} words`
  : `The previous description was ${v.words} words, which is too ${v.issue === 'too_long' ? 'long' : 'short'}. Rewrite it to be between ${v.min_words} and ${v.max_words} words`;

return [{
  json: {
    ...base,
    customer_rules: [...base.customer_rules, feedback]
  }
}];

// Final record. Descriptions that never passed the length check are
// returned with status "needs_review" instead of being dropped.
const v = $input.first().json;
const request = $('Build Description Request').first().json;
const candidate = request.candidate;

return [{
  json: {
    mpn: candidate.mpn,
    brand: candidate.brand,
    source_url: candidate.source_url,
    original_title: candidate.title,
    scraped_title: request.product.title,
    image_url: request.product.image_url,
    generated_description: v.description,
    word_count: v.words,
    attempts: v.attempt,
    status: v.valid ? 'valid' : 'needs_review',
    issue: v.issue
  }
}];
